package app.kinnect.live;
final class PolicyText {
static String title(String key){switch(key){
case "privacy":return "Chính sách quyền riêng tư";
case "community":return "Điều khoản sử dụng và Quy tắc cộng đồng";
case "child-safety":return "Tiêu chuẩn an toàn trẻ em của Kinnect";
default:return "Kinnect";}}
static String[][] rows(String key){switch(key){
case "privacy":return new String[][]{{"h2","Đơn vị vận hành và liên hệ"},{"p","Kinnect do Mr Ánh vận hành. Liên hệ hỗ trợ, quyền riêng tư và an toàn trẻ em: anhvn53@wru.vn. Chính sách áp dụng cho ứng dụng Android và web Kinnect; cập nhật ngày 29/10/2026."},{"h2","Dữ liệu được xử lý"},{"p","Kinnect lưu tên đăng nhập, tên hiển thị, mã băm mật khẩu, phiên đăng nhập; email nếu bạn liên kết hoặc dùng đăng nhập xã hội; hồ sơ và thông tin bạn tự nguyện chia sẻ như tuổi, thành phố, giới, xu hướng, sở thích, chiều cao/cân nặng; ảnh, video, bài viết, bình luận, tin nhắn, quan hệ theo dõi/kết bạn, báo cáo và lựa chọn đồng ý. Không cung cấp thông tin nhạy cảm mà bạn không muốn chia sẻ."},{"h2","Mục đích và quyền truy cập"},{"p","Dữ liệu dùng để vận hành tài khoản, hiển thị hồ sơ theo quyền riêng tư, kết nối thành viên, nhắn tin/gọi, phòng chống lạm dụng và xử lý báo cáo. Camera và micro chỉ được dùng khi bạn chọn chức năng liên quan và cấp quyền. Bộ chọn tệp hệ thống chỉ cấp quyền đối với tệp bạn chọn. Vị trí gần đúng chỉ được lấy khi bạn bật tìm quanh đây; bạn có thể tắt và xóa vị trí trong Cài đặt."},{"h2","Dịch vụ bên ngoài và AI"},{"p","Máy chủ và dịch vụ mạng/hosting, gồm Cloudflare, xử lý dữ liệu để truyền và vận hành dịch vụ. Ảnh hồ sơ, bài đăng và nội dung ảnh/video công khai có thể được gửi tới Cloudflare Workers AI hoặc NVIDIA để hỗ trợ kiểm duyệt. Trợ lý AI hỗ trợ chỉ được bật sau khi bạn chủ động đồng ý; khi bật, nội dung gửi và tối đa 6 tin nhắn liên quan trong cuộc trò chuyện hỗ trợ được gửi tới các nhà cung cấp đó. Bạn có thể tắt AI và tiếp tục liên hệ người quản trị. Không gửi mật khẩu, OTP, thông tin thanh toán hoặc dữ liệu nhạy cảm cho AI. Google/Facebook xử lý đăng nhập khi bạn chọn sử dụng. Nhà cung cấp chỉ được dùng trong phạm vi cung cấp dịch vụ và yêu cầu pháp luật áp dụng."},{"h2","Ai có thể xem và bảo mật"},{"p","Các thành viên chỉ thấy hồ sơ/nội dung theo lựa chọn hiển thị và quyền truy cập do máy chủ kiểm tra. Dữ liệu truyền qua HTTPS; mật khẩu được băm. Tin nhắn chưa có mã hóa đầu cuối: người vận hành máy chủ có khả năng truy cập dữ liệu lưu trữ khi vận hành, giải quyết yêu cầu và kiểm duyệt. Không mô tả tính năng này như bảo mật đầu cuối."},{"h2","Thời gian lưu và xóa"},{"p","Thông tin tài khoản, nội dung và lựa chọn được lưu trong thời gian tài khoản tồn tại, hoặc đến khi bạn xóa nội dung theo chức năng được hỗ trợ. Vị trí được lưu đến khi bạn tắt/xóa hoặc xóa tài khoản; vị trí cũ không được dùng để hiển thị quanh đây. Mã khôi phục hết hạn bị vô hiệu ngay khi hết hạn và được dọn trong chu kỳ bảo trì hàng giờ. Yêu cầu khôi phục mật khẩu được lưu tối đa 90 ngày; bạn có thể yêu cầu xóa sớm hơn qua kênh liên hệ riêng. Khi bạn xác nhận xóa tài khoản trong app hoặc web, hệ thống xóa dữ liệu liên quan khỏi cơ sở dữ liệu hoạt động và thu hồi mọi phiên ngay khi yêu cầu thành công. Nhóm có thành viên khác được chuyển chủ; các nội dung bạn gửi trong nhóm bị xóa. Bản sao lưu vận hành nếu có được cách ly, không dùng để phục vụ tài khoản và phải được xóa trong tối đa 30 ngày; không được khôi phục tài khoản đã xóa. Dữ liệu cần giữ do nghĩa vụ pháp lý hoặc xử lý an toàn sẽ được giới hạn phạm vi, mục đích và thời gian cần thiết, thông báo khi pháp luật cho phép."},{"h2","Quyền của bạn"},{"p","Bạn có thể sửa/ẩn thông tin, tắt vị trí, thay đổi quyền nhận tin, chặn/báo cáo và yêu cầu xóa tài khoản. Trong app: Cài đặt & riêng tư → Xóa tài khoản và dữ liệu. Ngoài app: https://app.kinnect.io.vn/delete-account. Không cần cài ứng dụng để dùng trang này. Nếu không đăng nhập được hoặc muốn yêu cầu truy cập/sửa/xóa dữ liệu cụ thể, liên hệ riêng anhvn53@wru.vn; chúng tôi xác minh quyền sở hữu trước khi xử lý. Không gửi mật khẩu, OTP hay dữ liệu nhạy cảm qua GitHub công khai."},{"h2","Độ tuổi, thay đổi và phạm vi"},{"p","Kinnect chỉ dành cho người đủ 18 tuổi, không cung cấp dịch vụ cho trẻ vị thành niên. Không được giả tuổi để đăng ký. Khi biết tài khoản chưa đủ tuổi hoặc có nguy cơ xâm hại trẻ em, chúng tôi sẽ hạn chế truy cập và xử lý theo quy trình an toàn. Xác nhận tuổi trong app là tự khai, không được quảng cáo như xác minh danh tính. Thay đổi đáng kể về dữ liệu sẽ được thông báo và xin lựa chọn lại khi cần. Hiện không tích hợp SDK quảng cáo hoặc bán dữ liệu cá nhân để quảng cáo."}};
case "community":return new String[][]{{"h2","Chấp nhận và độ tuổi"},{"p","Bạn phải đủ 18 tuổi và đồng ý các quy tắc này trước khi tạo hoặc chia sẻ nội dung trên Kinnect. Không mạo danh, khai sai độ tuổi hoặc dùng tài khoản người khác. Bạn có quyền rời dịch vụ và xóa tài khoản."},{"h2","Tôn trọng và đồng thuận"},{"p","Tôn trọng danh tính, giới, xu hướng tính dục và quyền riêng tư. Cấm kỳ thị, đe dọa, theo dõi, quấy rối, liên hệ sau khi bị chặn, lừa đảo và chia sẻ thông tin riêng của người khác. LGBT hoặc vẻ ngoài không phải lý do tự thân để đánh dấu vi phạm."},{"h2","Nội dung bị cấm"},{"p","Không đăng hoặc truyền nội dung bất hợp pháp, khiêu dâm, hành vi tình dục rõ ràng, kích dục, mua bán dịch vụ tình dục hoặc quan hệ đổi lợi ích; không bạo lực nghiêm trọng, kích động thù ghét, lừa đảo hoặc xâm phạm quyền tác giả. Không dùng ảnh, video, âm nhạc khi không có quyền sử dụng."},{"h2","Không khoan nhượng với xâm hại trẻ em"},{"p","Cấm CSAE/CSAM, dụ dỗ trẻ em, tống tiền tình dục, buôn bán người và mọi hành vi khai thác hoặc gây nguy hiểm tình dục cho trẻ em, kể cả hình ảnh do AI tạo. Không lưu, tải lại hoặc phát tán nội dung nghi ngờ để làm bằng chứng. Xem tiêu chuẩn công khai tại https://kinnect.io.vn/child-safety."},{"h2","Báo cáo và xử lý"},{"p","Dùng Báo cáo tại hồ sơ, bài viết, bình luận, tin nhắn, video hoặc kênh trợ giúp trong app. Bạn có thể chặn thành viên. Với sự cố an toàn trẻ em, nêu rõ loại sự cố và ID/nơi xuất hiện, không gửi lại hình ảnh vi phạm. Mr Ánh tiếp nhận qua anhvn53@wru.vn. Nội dung/tài khoản vi phạm có thể bị ẩn, gỡ, đình chỉ hoặc chấm dứt; báo cáo được con người xem xét, AI chỉ hỗ trợ. Bạn có thể liên hệ riêng để khiếu nại. Không cam kết có người trực 24/7 hoặc kết quả tự động từ AI."},{"h2","Trợ lý AI"},{"p","Câu trả lời AI được gắn nhãn, có thể sai và không đại diện cho một thao tác quản trị đã được thực hiện. Bạn có thể báo cáo trực tiếp tin nhắn AI và yêu cầu người quản trị. Không dùng AI để tạo nội dung bị cấm hoặc xử lý dữ liệu nhạy cảm của người khác."}};
case "child-safety":return new String[][]{{"h2","Cam kết và phạm vi"},{"p","Kinnect do Mr Ánh vận hành, chỉ dành cho người đủ 18 tuổi. Các tiêu chuẩn này áp dụng cho toàn bộ thành viên, nội dung, tin nhắn và hoạt động trên Kinnect, kể cả nội dung AI. Việc chỉ phục vụ người lớn không miễn trừ trách nhiệm bảo vệ trẻ em."},{"h2","Các hành vi bị cấm"},{"p","Nghiêm cấm xâm hại và bóc lột tình dục trẻ em (CSAE), tài liệu/hình ảnh xâm hại tình dục trẻ em (CSAM), dụ dỗ, tống tiền tình dục, buôn bán trẻ em, khai thác hoặc gây nguy hiểm tình dục cho trẻ em; bao gồm nội dung mô phỏng hoặc do AI tạo. Tài khoản trẻ vị thành niên không được sử dụng dịch vụ."},{"h2","Cách báo cáo"},{"p","Báo cáo ngay trong ứng dụng qua nút Báo cáo ở nội dung hoặc hồ sơ, hoặc Trợ giúp và hỗ trợ. Nêu rõ nguy cơ trẻ em và ID/vị trí nội dung, không tải xuống, lưu hoặc gửi lại hình ảnh vi phạm. Đầu mối: Mr Ánh, anhvn53@wru.vn. Nếu có nguy hiểm tức thời, liên hệ cơ quan khẩn cấp có thẩm quyền tại nơi bạn ở."},{"h2","Quy trình phản ứng"},{"p","Người phụ trách xem xét báo cáo, hạn chế khả năng tiếp cận nội dung/tài khoản nghi ngờ, gỡ nội dung CSAM khi biết rõ, chặn hành vi tiếp diễn và xử lý tài khoản theo mức độ. Bằng chứng cần thiết chỉ được giữ ở phạm vi tối thiểu, với truy cập hạn chế, cho việc xác minh hoặc nghĩa vụ báo cáo. Chúng tôi thực hiện nghĩa vụ báo cáo tới cơ quan có thẩm quyền theo pháp luật áp dụng; không chuyển tài liệu vi phạm qua GitHub hay các kênh công khai."},{"h2","Đầu mối và trách nhiệm"},{"p","Mr Ánh — anhvn53@wru.vn là đầu mối liên hệ về các thực hành phòng chống CSAE/CSAM và phối hợp với Google/cơ quan có thẩm quyền. Quy trình được vận hành thủ công với AI hỗ trợ, không quảng cáo giám sát 24/7. Báo cáo an toàn trẻ em cần được ưu tiên xử lý. Cập nhật ngày 29/10/2026."}};
default:return new String[][]{};}}
}
